/* Données du QCM en ligne de la page Flashcards + QCM (générées le 15/11/2026 depuis les QCM refondus). */
window.TJD_QCM_ESSAI = [{"id": "flashcards-qcm-intro-droit-l1", "matiere": "Introduction au droit L1 S1", "total": 387, "fiches": 22, "questions": [{"q": "Parmi ces exigences, lesquelles découlent du principe de sécurité juridique ?", "o": ["La loi doit être accessible et intelligible", "Le juge doit statuer en équité quand la loi est obscure", "Une réforme brutale doit prévoir des mesures transitoires", "Toute loi nouvelle doit s'appliquer aux procès déjà en cours"], "c": [0, 2], "j": "La sécurité juridique exige que chacun puisse connaître la règle et prévoir ses effets. Le Conseil constitutionnel en tire ainsi l'objectif d'accessibilité et d'intelligibilité de la loi (décision du 16 décembre 1999), et le Conseil d'État impose des mesures transitoires depuis l'arrêt KPMG de 2006. La proposition D décrit l'inverse, car une loi qui atteint les procès en cours bouleverse des situations sur lesquelles les parties comptaient.", "f": "La définition de la règle de droit"}, {"q": "Quel critère distingue la règle de droit des autres règles sociales ?", "o": ["Son but, qui est de maintenir l'ordre social", "Son origine, qui est humaine", "Sa sanction, organisée par l'État", "Sa forme, qui est écrite"], "c": [2], "j": "Seule la règle de droit peut être imposée par la contrainte publique, après la décision d'un juge, par exemple par une saisie ou une peine. La proposition A est tentante, mais la morale et la politesse servent aussi la vie en société. La forme écrite se retrouve aussi hors du droit, dans un code de déontologie, et la coutume reste une règle de droit sans être écrite.", "f": "La distinction de la règle de droit avec les autres règles sociales"}, {"q": "Que signifie l'expression summa divisio ?", "o": ["La division la plus haute du droit, en deux grandes familles de règles", "La division entre la loi écrite et la jurisprudence des juges", "L'addition de toutes les branches du droit en un ensemble", "La séparation entre le droit français et les droits étrangers"], "c": [0], "j": "Summa divisio signifie en latin « division la plus haute ». L'expression désigne donc la première coupure du droit, entre droit public et droit privé, avant toutes les subdivisions en branches. La proposition C joue sur le mot latin summa, mais celui-ci désigne ici le sommet, sans aucune idée d'addition ou de somme.", "f": "Les différentes branches du droit"}, {"q": "Combien d'ordres de juridiction existe-t-il en France ?", "o": ["Un seul ordre, coiffé par la Cour de cassation", "Deux ordres, judiciaire et administratif", "Trois ordres, judiciaire, administratif et constitutionnel", "Deux ordres, civil et pénal"], "c": [1], "j": "La France connaît deux ordres de juridiction. L'ordre judiciaire juge les litiges entre particuliers et les infractions, et l'ordre administratif juge les litiges avec l'administration. La proposition C est tentante, mais le Conseil constitutionnel reste en dehors de ces deux ordres, car il contrôle la conformité des lois à la Constitution sans trancher les litiges ordinaires.", "f": "L'organisation des juridictions"}, {"q": "Dans l'ordre juridique interne, quelle norme se place au sommet ?", "o": ["La Constitution du 4 octobre 1958", "Le droit de l'Union européenne", "La loi votée par le Parlement", "Les traités ratifiés, selon l'article 55"], "c": [0], "j": "Dans l'ordre interne, la Constitution du 4 octobre 1958 se place au sommet, avec les textes auxquels elle renvoie. Un traité contraire à la Constitution peut être ratifié seulement après sa révision (article 54). La proposition D est tentante, car l'article 55 place les traités au-dessus des lois, mais il les laisse sous la Constitution, comme l'a jugé le Conseil d'État dans l'arrêt Sarran de 1998.", "f": "Les sources écrites internes"}]}, {"id": "flashcards-qcm-constit-l1-s1", "matiere": "Droit constitutionnel L1 S1", "total": 445, "fiches": 25, "questions": [{"q": "Quels arrêts confient le contrôle de conventionnalité au juge ordinaire ?", "o": ["Jacques Vabre (1975)", "IVG (1975)", "Nicolo (1989)", "Liberté d'association (1971)"], "c": [0, 2], "j": "Dans l'arrêt Jacques Vabre (Chambre mixte, 24 mai 1975), la Cour de cassation écarte une loi contraire au traité de Rome. Le Conseil d'État fait de même dans l'arrêt Nicolo (Assemblée, 20 octobre 1989). Le juge ordinaire vérifie donc qu'une loi respecte les traités. La proposition B est tentante, car la décision IVG du 15 janvier 1975 traite de ce contrôle, mais le Conseil constitutionnel y refuse de l'exercer.", "f": "Qu'est-ce que le droit constitutionnel ?"}, {"q": "Pourquoi les constitutions sont-elles souvent rédigées en termes brefs et généraux ?", "o": ["Pour que le Parlement puisse les modifier par une loi ordinaire", "Pour durer et s'appliquer à des situations imprévues", "Pour que le juge n'ait jamais besoin de les interpréter", "Pour respecter une exigence posée par le droit international"], "c": [1], "j": "Les rédacteurs choisissent des formules brèves et générales pour que la Constitution dure et s'applique à des situations qu'ils ne pouvaient pas prévoir. Cette brièveté oblige ensuite à interpréter le texte. La proposition C est donc fausse, car plus un texte est général, plus le juge doit l'interpréter. La proposition A contredit la rigidité de la Constitution de 1958, qui se révise selon l'article 89.", "f": "La méthode du droit constitutionnel"}, {"q": "Quels sont les trois éléments constitutifs de l'État selon la théorie classique ?", "o": ["Le territoire, la souveraineté et la reconnaissance par les États", "La nation, le peuple et la citoyenneté", "Le territoire, la Constitution et le gouvernement", "Le territoire, la population et la puissance publique souveraine"], "c": [3], "j": "Pour la théorie classique, formulée par Georg Jellinek en 1900, l'État réunit un territoire, une population et une puissance publique souveraine, qui commande sans dépendre d'un pouvoir supérieur. La proposition A se défend en apparence, car la reconnaissance compte en droit international, mais la théorie déclarative, majoritaire, y voit un simple constat de l'existence de l'État.", "f": "Les composantes de l'État"}, {"q": "Quelle forme d'État est la plus répandue dans le monde ?", "o": ["L'État unitaire", "L'État fédéral", "L'État régional", "La confédération d'États"], "c": [0], "j": "L'État unitaire est la forme la plus répandue, puisque la grande majorité des États membres de l'ONU l'adoptent, dont la France, le Japon ou le Portugal. En revanche, on compte seulement environ vingt-cinq États fédéraux, comme les États-Unis, l'Allemagne ou l'Inde. La proposition B se défend en apparence, car ces États fédéraux sont souvent très peuplés et très étendus.", "f": "L'État unitaire"}, {"q": "Quel acte fonde un État fédéral ?", "o": ["Un traité international", "Une loi organique", "Une adhésion à l'ONU", "Une Constitution fédérale"], "c": [3], "j": "L'État fédéral naît d'une Constitution, qui crée un nouvel État et répartit les compétences entre la fédération et les États fédérés. La proposition A se défend en apparence, mais un traité fonde une confédération, comme les Articles de la Confédération américaine de 1781, dans laquelle chaque État gardait sa souveraineté.", "f": "L'État fédéral"}]}, {"id": "flashcards-qcm-hist-droit-l1", "matiere": "Histoire du droit L1 S1", "total": 356, "fiches": 20, "questions": [{"q": "Parmi ces documents, lesquels sont des sources directes, c'est-à-dire des textes qui énoncent eux-mêmes une règle de droit ?", "o": ["Les capitulaires carolingiens", "Les ordonnances royales", "L'Histoire des Francs de Grégoire de Tours", "Les vies de saints rédigées par des moines"], "c": [0, 1], "j": "Les capitulaires et les ordonnances royales posent eux-mêmes des règles, que les sujets doivent respecter. Ce sont donc des sources directes. Le récit de Grégoire de Tours, évêque du VIe siècle, et les vies de saints décrivent des événements. L'historien en tire des informations sur le droit appliqué, mais ces textes restent des sources indirectes.", "f": "Qu'est-ce que l'histoire des institutions ?"}, {"q": "Selon la tradition, en quelle année Rome est-elle fondée ?", "o": ["44 av. J.-C.", "509 av. J.-C.", "753 av. J.-C.", "1184 av. J.-C."], "c": [2], "j": "La tradition romaine place la fondation de Rome par Romulus en 753 av. J.-C. Les historiens y voient pourtant une date symbolique, que l'archéologie confirme seulement en partie. La proposition B est tentante, car 509 av. J.-C. est aussi une date de départ, mais elle marque la chute de la royauté et la naissance de la République. L'année 1184 av. J.-C., en D, correspond à la date traditionnelle de la prise de Troie, d'où Énée serait parti vers l'Italie.", "f": "La royauté et la naissance de la République romaine"}, {"q": "Combien de temps dure une magistrature ordinaire sous la République romaine ?", "o": ["Cinq ans", "Une année", "Six mois", "Dix-huit mois"], "c": [1], "j": "Le principe d'annualité limite chaque magistrature ordinaire à un an. À la fin de l'année, le magistrat redevient un simple citoyen et peut devoir rendre des comptes. La proposition D est tentante, car les censeurs restent en fonction dix-huit mois, mais ils ne sont élus que tous les cinq ans et forment une exception. Les six mois, en C, correspondent à la dictature.", "f": "Les institutions de la République romaine"}, {"q": "En quelle année Auguste fonde-t-il le Principat ?", "o": ["31 av. J.-C.", "2 av. J.-C.", "27 av. J.-C.", "14 apr. J.-C."], "c": [2], "j": "En janvier 27 av. J.-C., Octave fait mine de rendre la République au Sénat, qui lui donne en retour le titre d'Auguste. Le Principat commence donc ce jour-là. La proposition A est tentante, car 31 av. J.-C. est la victoire d'Actium, qui le laisse seul maître de Rome, mais le régime naît quatre ans plus tard. Auguste meurt en 14 apr. J.-C.", "f": "Du Principat au Dominat : l'Empire romain"}, {"q": "Quelle idée politique la res publica romaine lègue-t-elle à l'Europe ?", "o": ["Celle d'un pouvoir confondu avec la personne du roi", "Celle d'un pouvoir impersonnel, distinct des gouvernants", "Celle d'un pouvoir partagé entre les seigneurs locaux", "Celle d'un pouvoir reçu de Dieu par le souverain"], "c": [1], "j": "Avec la res publica, Rome invente un pouvoir qui appartient à la communauté et survit aux hommes qui l'exercent pour un temps. C'est la première ébauche de l'État. La proposition A est tentante, car elle décrit bien une forme de pouvoir connue de l'histoire, mais c'est celle des royaumes francs, où le roi traite le royaume comme son patrimoine.", "f": "L'héritage politique et juridique de Rome"}]}, {"id": "flashcards-qcm-constit-l1-s2", "matiere": "Droit constitutionnel L1 S2", "total": 418, "fiches": 24, "questions": [{"q": "Quels mécanismes ont rendu les gouvernements de la IVe République instables ?", "o": ["La double investiture du Président du Conseil puis de son équipe", "Les démissions spontanées avant tout vote de censure", "Une dissolution soumise à des conditions difficiles à réunir", "La révocation des gouvernements par le Président de la République"], "c": [0, 1, 2], "j": "Trois pratiques ont fragilisé les gouvernements. Le Président du Conseil était investi seul, puis il devait faire investir son équipe, ce qui donnait deux occasions de chute. De plus, les gouvernements démissionnaient dès qu'une majorité hostile apparaissait, sans attendre la censure. Enfin, l'article 51 réservait la dissolution au cas de deux crises ministérielles en dix-huit mois, si bien qu'elle a servi une seule fois. La proposition D est fausse, car le Président de la IVe République n'avait aucun pouvoir de révoquer le Gouvernement.", "f": "L'échec de la IVe République et la crise de mai 1958"}, {"q": "À quel article de la Constitution de 1946 la loi du 3 juin 1958 déroge-t-elle ?", "o": ["L'article 45, sur l'investiture", "L'article 51, sur la dissolution", "L'article 90, sur la procédure de révision", "L'article 13, sur le vote de la loi"], "c": [2], "j": "L'article 90 de la Constitution de 1946 organisait une révision longue, lancée par l'Assemblée et soumise à plusieurs votes. La loi du 3 juin 1958 y déroge pour confier la rédaction d'une nouvelle Constitution au gouvernement du général de Gaulle, avec une adoption par référendum. La proposition B est tentante, car l'article 51 est célèbre pour avoir rendu la dissolution presque impossible, mais il concerne seulement la dissolution.", "f": "L'élaboration et l'adoption de la Constitution du 4 octobre 1958"}, {"q": "Quelle est la valeur juridique des cinq principes de la loi du 3 juin 1958 ?", "o": ["Une valeur législative, comme une loi ordinaire", "Une valeur réglementaire, comme un décret", "Une valeur politique, sans force obligatoire", "Une valeur constitutionnelle qui lie le rédacteur"], "c": [3], "j": "Les cinq principes figurent dans une loi constitutionnelle, si bien qu'ils ont une valeur constitutionnelle et s'imposent au gouvernement chargé de rédiger le texte. Le Conseil d'État a d'ailleurs vérifié leur respect avant le référendum. Il serait facile de choisir C, car ces principes sont rédigés en termes généraux, mais leur source constitutionnelle les rend obligatoires.", "f": "Les principes fondateurs et la nature juridique du régime"}, {"q": "Comment le Président de la République est-il élu dans le texte initial de 1958 ?", "o": ["Par le Parlement réuni en Congrès à Versailles", "Par un collège d'environ 80 000 grands électeurs", "Au suffrage universel direct, à deux tours", "Par l'Assemblée nationale, à la majorité absolue"], "c": [1], "j": "En 1958, le Président est élu par un collège d'environ 80 000 grands électeurs, composé surtout d'élus locaux, auxquels s'ajoutent les parlementaires. Le passage au suffrage universel direct date de la révision de 1962. On pourrait retenir la proposition A, car les Présidents de la IIIe et de la IVe République étaient élus par les deux chambres réunies, ce que les rédacteurs de 1958 ont voulu abandonner.", "f": "Le statut du Président de la République"}, {"q": "Qu'est-ce qui définit un pouvoir propre du Président de la République ?", "o": ["L'accord obligatoire du Premier ministre", "L'absence de contreseing prévue par l'article 19", "Un vote préalable de l'Assemblée nationale et du Sénat", "L'avis conforme du Conseil constitutionnel"], "c": [1], "j": "Un pouvoir propre est un acte que le Président accomplit seul, sans la signature du Premier ministre ou d'un ministre, appelée contreseing. L'article 19 énumère ces actes dispensés de contreseing. La proposition A décrit au contraire les pouvoirs partagés, qui exigent cette signature et engagent ainsi la responsabilité du Gouvernement devant l'Assemblée.", "f": "Les pouvoirs propres du Président de la République"}]}, {"id": "flashcards-qcm-penal-general-l1", "matiere": "Droit pénal L1 S2", "total": 350, "fiches": 20, "questions": [{"q": "Quelles différences séparent le droit pénal de la responsabilité civile ?", "o": ["En principe, le ministère public exerce l'action pénale, la victime l'action en réparation", "Le droit pénal exige toujours un dommage, la responsabilité civile jamais", "L'amende pénale est versée à la victime pour compenser le préjudice qu'elle a subi", "Le droit pénal punit l'auteur, la responsabilité civile répare le dommage de la victime"], "c": [0, 3], "j": "Le procureur de la République exerce l'action publique au nom de la société, alors que la victime agit pour obtenir réparation. Le droit pénal cherche à punir, la responsabilité civile à indemniser. La proposition C est fausse, car l'amende pénale va au Trésor public, et la victime obtient des dommages et intérêts. La proposition B inverse la logique, puisque la tentative est punie sans dommage, alors que la responsabilité civile suppose un préjudice.", "f": "La notion de droit pénal et ses branches"}, {"q": "Quelle a été la première limite apportée à la vengeance privée ?", "o": ["La paix de Dieu", "La loi du talion", "Le système composé", "La justice royale"], "c": [1], "j": "La loi du talion, « œil pour œil, dent pour dent », impose que la riposte ne dépasse pas le mal subi. C'est la première mesure posée à la vengeance. On peut hésiter avec la proposition C, car le système composé limite lui aussi la vengeance, mais il vient après, quand la victime accepte une somme d'argent à la place de la riposte. La justice royale, en D, s'impose bien plus tard.", "f": "L'histoire du droit pénal"}, {"q": "Quels textes composent le bloc de constitutionnalité ?", "o": ["La Constitution de 1958, la Déclaration de 1789, le Préambule de 1946 et la Charte de 2004", "La Constitution de 1958, le Préambule de 1946, la Charte de 2004 et les principes généraux du droit", "La Constitution de 1958, la Déclaration de 1789, les lois organiques et la Charte de 2004", "La Constitution de 1958, la Déclaration de 1789, le Préambule de 1946 et la Convention européenne"], "c": [0], "j": "Le bloc de constitutionnalité réunit les textes qui ont valeur constitutionnelle, à savoir la Constitution de 1958, la Déclaration des droits de l'homme de 1789, le Préambule de 1946 et la Charte de l'environnement de 2004. La réponse D trompe facilement, car la Convention européenne des droits de l'homme protège les mêmes libertés, mais elle a une valeur supérieure aux lois et inférieure à la Constitution. Les lois organiques, en C, sont seulement des normes de référence ponctuelles.", "f": "Les sources du droit pénal"}, {"q": "Que commande le principe de légalité criminelle ?", "o": ["Toute loi pénale doit être votée à la majorité absolue des membres du Parlement", "Nul n'est puni sans une loi qui a défini à l'avance l'infraction et la peine", "Nul n'est puni sans un jugement rendu par un tribunal composé de magistrats", "Toute infraction doit être punie de la même peine, quel que soit son auteur"], "c": [1], "j": "Le principe de légalité veut qu'une personne ne soit punie que si une loi existait au moment des faits, définissait le comportement interdit et fixait la peine encourue. Le piège se trouve dans la proposition C, car elle décrit une garantie réelle du procès pénal, celle d'un tribunal établi par la loi, mais elle relève de la légalité de la procédure. L'égalité de peine, en D, contredit l'individualisation des peines.", "f": "Le principe de légalité criminelle (fondements)"}, {"q": "Que désigne le mot « corollaire » à propos du principe de légalité ?", "o": ["Une conséquence qui découle directement du principe", "Une exception qui réduit la portée du principe", "Une condition préalable à l'application du principe", "Une règle coutumière qui vient compléter le principe"], "c": [0], "j": "Un corollaire est une conséquence logique d'un principe. Du principe de légalité découlent des obligations pour le législateur, qui doit écrire des textes clairs, et pour le juge, qui doit les interpréter strictement. La réponse B trompe facilement, car le principe connaît aussi des limites, comme la tolérance d'une certaine imprécision, mais une limite restreint le principe au lieu d'en découler.", "f": "Les corollaires du principe de légalité"}]}, {"id": "flashcards-qcm-famille-l1-s2", "matiere": "Droit de la famille L1 S2", "total": 388, "fiches": 22, "questions": [{"q": "Que doit prouver le fiancé qui demande réparation après une rupture ?", "o": ["Une faute dans les circonstances de la rupture", "Un préjudice qu'il a réellement subi", "Un lien de causalité entre la faute et le préjudice", "Une mise en demeure adressée avant la rupture"], "c": [0, 1, 2], "j": "L'article 1240 exige trois éléments cumulatifs, à savoir une faute, un préjudice et un lien de causalité qui rattache le préjudice à la faute. La proposition D est tentante, car la mise en demeure existe en matière contractuelle, par exemple pour réclamer un paiement. Elle n'a aucun rôle ici, puisque les fiancés ne sont liés par aucun contrat.", "f": "Les fiançailles et la liberté du mariage"}, {"q": "Quelle loi a fixé l'âge du mariage à dix-huit ans révolus pour les deux futurs époux ?", "o": ["La loi du 11 juillet 1975", "La loi du 17 mai 2013", "La loi du 23 mars 2019", "La loi du 4 avril 2006"], "c": [3], "j": "La loi du 4 avril 2006, adoptée pour lutter contre les mariages forcés, a relevé l'âge de la femme de quinze à dix-huit ans et aligné les deux sexes (article 144). La proposition B semble défendable, car l'article 144 porte aujourd'hui la marque de la loi du 17 mai 2013. Pourtant, cette loi a seulement réécrit le texte pour viser aussi les couples de même sexe.", "f": "Les conditions de fond du mariage"}, {"q": "Que désignent les conditions de forme du mariage ?", "o": ["Les règles sur le consentement, l'âge et les empêchements", "Les règles qui fixent les biens et les pouvoirs des époux", "Les règles qui organisent la publication et la célébration", "Les règles qui sanctionnent les manquements aux devoirs conjugaux"], "c": [2], "j": "Les conditions de forme décrivent la façon dont le mariage se prépare et se célèbre, depuis le dossier remis à la mairie jusqu'à l'échange des consentements devant l'officier. La proposition A est tentante, car ces règles concernent aussi la formation du mariage. Elles forment pourtant les conditions de fond, qui portent sur les personnes elles-mêmes et leur volonté.", "f": "Les conditions de forme et la célébration du mariage"}, {"q": "Quelle nullité sanctionne l'erreur sur les qualités essentielles du conjoint ?", "o": ["Une nullité relative, réservée à l'époux qui s'est trompé", "Une nullité absolue, ouverte à tout intéressé pendant trente ans", "Une séparation de corps prononcée à la demande de l'époux trompé", "Un divorce pour faute prononcé aux torts de l'époux qui a menti"], "c": [0], "j": "L'erreur protège la volonté d'un seul époux, donc l'article 180, alinéa 2, réserve l'action à « l'autre époux », celui qui s'est trompé. La proposition B peut tromper, car le délai de trente ans existe. Il concerne pourtant les causes d'ordre public énumérées par l'article 184, comme la bigamie ou l'inceste.", "f": "Les nullités du mariage et le mariage putatif"}, {"q": "À qui s'appliquent les règles des articles 212 à 226 du code civil ?", "o": ["Aux seuls époux mariés sous la communauté légale", "À tous les époux, quel que soit leur régime matrimonial", "Aux seuls époux qui n'ont signé aucun contrat de mariage", "Aux époux et aux partenaires liés par un Pacs"], "c": [1], "j": "L'article 226 rend ces règles applicables par le seul effet du mariage, quel que soit le régime matrimonial des époux. On parle de régime primaire, car il forme le socle commun à tous les couples mariés. La proposition C a l'air exacte, car le contrat de mariage choisit le régime des biens. Il ne peut pourtant écarter ces règles que là où elles réservent les conventions matrimoniales.", "f": "Les devoirs personnels entre époux"}]}, {"id": "flashcards-qcm-personnes-l1", "matiere": "Droit des personnes L1", "total": 388, "fiches": 22, "questions": [{"q": "Parmi ces groupements, lesquels ont la <strong>personnalité morale</strong> ?", "o": ["Une association déclarée à la préfecture", "Une indivision entre plusieurs héritiers", "Une société immatriculée au registre du commerce", "Une association qui n'a jamais été déclarée"], "c": [0, 2], "j": "L'association déclarée obtient la capacité juridique grâce à sa déclaration, prévue par la loi du 1er juillet 1901. De plus, la société acquiert la personnalité morale à son immatriculation (art. 1842 C. civ.). L'indivision, en B, réunit seulement plusieurs propriétaires d'un même bien, chacun restant titulaire de ses droits. L'association non déclarée, en D, existe comme contrat entre ses membres, mais elle n'a ni patrimoine propre ni capacité d'agir en justice.", "f": "La naissance et la personnalité juridique"}, {"q": "Que signifie l'adage <strong>infans conceptus pro nato habetur quoties de commodis ejus agitur</strong> ?", "o": ["L'enfant conçu acquiert la personnalité dès la conception, en toute matière", "L'enfant conçu pendant le mariage a pour père le mari de sa mère", "L'enfant conçu est tenu pour né chaque fois qu'il y va de son intérêt", "L'enfant conçu est tenu pour né s'il atteint le seuil de viabilité médical"], "c": [2], "j": "L'adage romain traite l'enfant simplement conçu comme s'il était déjà né, à chaque fois que cela lui apporte un avantage, par exemple pour hériter de son père mort pendant la grossesse. La proposition A ressemble à la bonne réponse, mais elle oublie la limite de l'intérêt de l'enfant. En dehors de ce cas, la personnalité commence à la naissance. La proposition B reprend une autre règle, la présomption de paternité du mari, inscrite à l'article 312 C. civ.", "f": "Le statut juridique de l'enfant à naître"}, {"q": "Quel texte fixe les critères qui permettent de constater la mort d'une personne ?", "o": ["Le Code civil, qui en donne une définition générale", "Le Code de la santé publique, qui fixe les critères médicaux", "L'acte de décès, que l'officier de l'état civil rédige à la mairie", "La jurisprudence de la Cour de cassation, au cas par cas"], "c": [1], "j": "Le Code civil emploie le mot « mort » sans le définir. Les critères se trouvent donc dans le Code de la santé publique, aux articles R. 1232-1 et suivants CSP, issus d'un décret du 2 décembre 1996. Le médecin y trouve les signes cliniques qu'il doit relever, comme l'absence totale de conscience et de respiration spontanée. La proposition C ressemble à la bonne réponse, mais l'officier de l'état civil enregistre un décès déjà constaté par le médecin.", "f": "La mort"}, {"q": "Quelle situation correspond à l'<strong>absence</strong> au sens juridique ?", "o": ["Une personne morte avec certitude, mais dont le corps reste introuvable", "Une personne disparue lors d'un naufrage, dont le corps reste introuvable", "Une personne détenue à l'étranger, qui donne de ses nouvelles à sa famille", "Une personne partie sans laisser de nouvelles, dont on ignore si elle vit"], "c": [3], "j": "L'absence suppose un doute sur l'existence de la personne. Elle a cessé de paraître à son domicile sans donner de nouvelles, et personne ne sait si elle est vivante ou morte (art. 112 C. civ.). La proposition B semble juste, mais un naufrage est une circonstance qui met la vie en danger, ce qui relève de la disparition et du jugement déclaratif de décès (art. 88 C. civ.). Enfin, la proposition A relève de l'article 88, qui vise le décès certain sans corps.", "f": "La mort incertaine : absence et disparition"}, {"q": "Le mot « <strong>état civil</strong> » désigne deux réalités. Lesquelles ?", "o": ["Le statut fiscal d'une personne et sa situation familiale déclarée aux impôts", "Les qualités qui situent une personne et le service public qui les enregistre", "Le casier judiciaire d'une personne et son inscription sur les listes électorales", "La nationalité d'une personne et son domicile, inscrits sur sa carte d'identité"], "c": [1], "j": "Au premier sens, l'état civil réunit les qualités qui situent une personne dans la société et dans sa famille, comme son nom, son sexe, sa filiation ou sa situation de couple. Au second sens, c'est le service public qui inscrit ces qualités dans des registres, tenu dans chaque commune par l'officier de l'état civil. La proposition A ressemble à la bonne réponse, car l'administration fiscale demande la situation familiale, mais elle se contente d'utiliser les données de l'état civil.", "f": "L'état civil"}]}, {"id": "flashcards-qcm-relations-internationales-l1", "matiere": "Relations internationales L1", "total": 335, "fiches": 19, "questions": [{"q": "Lesquels de ces exemples relèvent des relations transnationales ?", "o": ["Une ONG qui soigne des blessés sur plusieurs continents", "Un traité de commerce négocié par deux gouvernements", "Une entreprise française qui ouvre une usine au Brésil", "Un sommet de chefs d'État consacré au climat"], "c": [0, 2], "j": "Les <strong>relations transnationales</strong> franchissent les frontières sans passer par les États, comme une organisation non gouvernementale ou une entreprise qui s'installe à l'étranger. La proposition D est tentante, car le climat concerne toute la planète, mais un sommet de chefs d'État reste une relation interétatique. Le traité de la proposition B relève lui aussi des relations entre États.", "f": "La notion de relations internationales et de société internationale"}, {"q": "Comment le réalisme décrit-il le monde international ?", "o": ["Comme un marché où la coopération rapporte à tous les États", "Comme un monde anarchique où chaque État doit assurer sa survie", "Comme un espace construit par les idées et les identités", "Comme un système où un centre riche domine une périphérie"], "c": [1], "j": "Pour le <strong>réalisme</strong>, aucun pouvoir n'est placé au-dessus des États. Chacun doit donc compter sur sa propre puissance pour survivre. La proposition A est tentante, car les réalistes admettent que les États négocient, mais l'idée d'une coopération profitable à tous appartient au libéralisme. La proposition C décrit le constructivisme, et la proposition D le système-monde de Wallerstein.", "f": "Les grandes théories des relations internationales"}, {"q": "Quels historiens français ont appelé « forces profondes », en 1964, les réalités durables qui orientent les choix des dirigeants ?", "o": ["Braudel et Bloch", "Aron et Merle", "Renouvin et Duroselle", "Mackinder et Mahan"], "c": [2], "j": "Pierre Renouvin et Jean-Baptiste Duroselle emploient l'expression <strong>forces profondes</strong> dans leur Introduction à l'histoire des relations internationales (1964). Ils visent la géographie, la démographie, les intérêts économiques et les mentalités collectives, qui orientent les décisions des gouvernants. On peut hésiter avec la proposition A, car Fernand Braudel a étudié les évolutions lentes, qu'il appelle la longue durée, mais l'expression vient de Renouvin et Duroselle.", "f": "Les facteurs des relations internationales"}, {"q": "Quel principe les traités de Westphalie de 1648 consacrent-ils dans les relations entre États ?", "o": ["La sécurité collective contre l'agresseur", "L'égalité souveraine des États", "La primauté du pape sur les princes", "Le droit des peuples à disposer d'eux-mêmes"], "c": [1], "j": "Après 1648, chaque État décide seul sur son territoire, et aucun ne reconnaît d'autorité au-dessus de lui. Les États sont donc souverains et égaux en droit. Le piège se trouve en D, car cette proposition touche aussi à l'indépendance, mais le droit des peuples à disposer d'eux-mêmes s'impose seulement au XXe siècle, avec Wilson puis l'article 1er §2 de la Charte des Nations unies.", "f": "Histoire des relations internationales : des origines à 1945"}, {"q": "Quel texte crée l'Organisation des Nations unies en 1945 ?", "o": ["La Charte de l'Atlantique", "La déclaration des Nations unies", "La Charte de San Francisco", "Les accords de Bretton Woods"], "c": [2], "j": "La Charte des Nations unies est signée à San Francisco le 26 juin 1945 et entre en vigueur le 24 octobre 1945. On peut hésiter avec la proposition A, car la Charte de l'Atlantique, signée par Roosevelt et Churchill en août 1941, annonce un système de sécurité générale, mais elle ne crée aucune organisation. La déclaration des Nations unies du 1er janvier 1942, en B, réunit seulement les États en guerre contre l'Axe.", "f": "Histoire des relations internationales : de 1945 à nos jours"}]}, {"id": "flashcards-qcm-da-l2-s1", "matiere": "Droit administratif L2 S1", "total": 380, "fiches": 22, "questions": [{"q": "Quelles affirmations décrivent le système dualiste français ?", "o": ["Deux ordres de juridiction coexistent, chacun avec sa juridiction suprême", "L'administration est jugée par les mêmes tribunaux que les particuliers", "Un juge spécialisé applique à l'administration des règles distinctes du droit privé", "Le Tribunal des conflits sert de juridiction d'appel commune aux deux ordres"], "c": [0, 2], "j": "Dans le <strong>système dualiste</strong>, deux ordres coexistent. D'un côté, l'ordre judiciaire a pour juridiction suprême la Cour de cassation. De l'autre, l'ordre administratif a pour juridiction suprême le Conseil d'État, et son juge applique à l'administration un droit propre, le droit administratif. La proposition B décrit au contraire le système moniste, celui du Royaume-Uni ou des États-Unis. La proposition D se trompe sur le rôle du Tribunal des conflits, car il tranche seulement les questions de compétence entre les deux ordres, sans juger les affaires en appel.", "f": "La naissance historique du droit administratif"}, {"q": "Que retient l'approche organique du droit administratif ?", "o": ["La nature de l'activité exercée par l'auteur de l'acte", "La qualité de l'auteur, qui est une personne publique", "Le but d'intérêt général poursuivi par l'acte", "La présence de prérogatives de puissance publique"], "c": [1], "j": "L'<strong>approche organique</strong> regarde qui agit. Le droit administratif serait alors le droit des personnes publiques, comme l'État ou une commune. La proposition A décrit en revanche l'approche matérielle, qui s'attache à l'activité exercée, par exemple le service public ou la police administrative.", "f": "La notion et les critères du droit administratif"}, {"q": "Pourquoi dit-on que le droit administratif est un droit inégalitaire ?", "o": ["L'administration a des prérogatives et des sujétions qu'ignorent les particuliers", "Les usagers d'un même service public sont traités de façon différente", "Le juge administratif tranche toujours en faveur de l'administration", "Les règles applicables changent selon la commune où l'on se trouve"], "c": [0], "j": "Le droit administratif est <strong>inégalitaire</strong> parce que l'administration occupe une position différente de celle des particuliers. Elle dispose de prérogatives, comme le privilège du préalable, qui lui permettent d'imposer ses décisions. Elle supporte aussi des sujétions, comme l'obligation d'assurer la continuité du service. On peut être tenté par la proposition B, mais elle contredit le principe d'égalité des usagers, que le service public doit respecter.", "f": "Les caractères du droit administratif"}, {"q": "Qu'est-ce que le dualisme juridictionnel ?", "o": ["Un seul ordre de juridiction, avec une chambre réservée à l'administration", "Deux juges qui statuent ensemble dans chaque tribunal de première instance", "Deux ordres de juridiction séparés, chacun avec sa juridiction suprême", "La séparation entre la justice civile et la justice pénale au sein de l'ordre judiciaire"], "c": [2], "j": "Le <strong>dualisme juridictionnel</strong> signifie que la France compte deux ordres de juridiction. L'ordre judiciaire, au sommet duquel se trouve la Cour de cassation, juge ainsi les litiges entre particuliers et les infractions. L'ordre administratif, au sommet duquel se trouve le Conseil d'État, juge l'administration. La proposition D est tentante, mais la justice civile et la justice pénale appartiennent toutes deux à l'ordre judiciaire.", "f": "Le principe de séparation des deux ordres de juridiction"}, {"q": "Quelle juridiction est juge de droit commun du contentieux administratif en premier ressort ?", "o": ["Le tribunal administratif", "Le Conseil d'État", "La cour administrative d'appel", "Le tribunal judiciaire"], "c": [0], "j": "L'article L. 211-1 du Code de justice administrative fait des tribunaux administratifs les juges de droit commun du contentieux administratif en premier ressort. On en compte 42, en métropole et outre-mer. Le piège se trouve en B, car le Conseil d'État juge certaines affaires en premier et dernier ressort, comme les recours contre les décrets, mais seulement dans les cas que les textes lui attribuent.", "f": "L'organisation de la juridiction administrative"}]}, {"id": "flashcards-qcm-contrats-l2-s1", "matiere": "Droit des contrats L2 S1", "total": 473, "fiches": 28, "questions": [{"q": "Parmi ces actes, lesquels sont des actes juridiques unilatéraux ?", "o": ["Le testament par lequel une personne désigne ses héritiers", "La donation d'un appartement acceptée par le donataire", "La reconnaissance d'un enfant par son père devant l'officier d'état civil", "La gestion des affaires d'un voisin parti en voyage"], "c": [0, 2], "j": "Un acte juridique unilatéral est une manifestation de volonté d'une seule personne, destinée à produire des effets de droit (article 1100-1). Le testateur décide seul du sort de ses biens, et le père reconnaît seul son enfant. La proposition B semble juste, car seul le donateur s'oblige dans une donation, ce qui en fait un contrat unilatéral, mais elle suppose l'accord du donataire et reste donc un acte conventionnel. La gestion d'affaires, en D, est un quasi-contrat, donc un fait juridique.", "f": "Les sources des obligations et la notion de contrat"}, {"q": "Quel principe gouverne la formation des contrats en droit français ?", "o": ["Le contrat se forme par la remise de la chose qui en fait l'objet", "Le contrat se forme par un écrit signé par chacune des parties", "Le contrat se forme par le seul échange des consentements", "Le contrat se forme par un acte reçu par un notaire ou un avocat"], "c": [2], "j": "L'article 1172, alinéa 1er, du Code civil pose que les contrats sont par principe consensuels, et l'article 1109 précise que le contrat consensuel se forme par le seul échange des consentements, quel qu'en soit le mode d'expression. Une vente conclue oralement au marché est donc valable. On peut hésiter avec la proposition B, car un écrit est souvent rédigé, mais il sert le plus souvent à prouver le contrat. Seuls les contrats solennels exigent une forme pour être valables, et les contrats réels exigent la remise d'une chose.", "f": "La classification des contrats"}, {"q": "Que signifie le consensualisme en droit des contrats ?", "o": ["Le contrat doit être constaté par un écrit pour produire ses effets", "Le contrat se forme par le seul accord des volontés, sans forme imposée", "Le contrat exige l'accord des parties sur chacune de ses clauses", "Le contrat oral reste valable, mais seulement entre deux particuliers"], "c": [1], "j": "Le consensualisme, posé par l'article 1172, alinéa 1er, signifie que le contrat se forme par le seul accord des volontés, sans écrit ni autre formalité. La loi impose une forme seulement pour les contrats solennels, par exemple la donation, passée devant notaire (article 931). La proposition C est tentante, mais l'accord doit porter sur les éléments essentiels du contrat (article 1114), et les points secondaires peuvent rester à régler. La proposition A confond la validité du contrat et sa preuve.", "f": "Les principes directeurs du droit des contrats"}, {"q": "Un bail est signé le 3 mars 2015 et un litige naît en 2020. Quel droit le juge applique-t-il au contrat ?", "o": ["L'ordonnance du 10 février 2016, dans sa version d'origine de 2016", "Le texte issu de la loi de ratification du 20 avril 2018", "L'ancien Code civil et la jurisprudence rendue sous son empire", "Le droit en vigueur au jour du litige, soit le texte ratifié"], "c": [2], "j": "Le contrat est conclu avant le 1er octobre 2016, donc il reste soumis à la loi ancienne selon l'article 9, alinéa 2, de l'ordonnance du 10 février 2016. Le juge applique l'ancien Code civil et la jurisprudence construite sur ces textes, même si le litige naît en 2020. La proposition D semble juste, car un procès se juge souvent avec les règles du moment, mais en matière contractuelle la date de conclusion du contrat décide du droit applicable, pour respecter les prévisions des parties.", "f": "L'application de la réforme dans le temps"}, {"q": "Selon l'article 1112, alinéa 1er, du Code civil, quel est le régime de la rupture des négociations précontractuelles ?", "o": ["Libre, mais elle doit respecter les exigences de la bonne foi", "Libre seulement si aucune des parties n'a engagé de dépense", "Interdite sans un préavis raisonnable laissé à l'autre partie", "Fautive dès que les négociations ont atteint un stade avancé"], "c": [0], "j": "L'article 1112, alinéa 1er, déclare libres l'initiative, le déroulement et la rupture des négociations, puis exige qu'ils satisfassent impérativement aux exigences de la bonne foi. Chacun peut donc arrêter de négocier, mais sans déloyauté. La proposition D semble juste, car l'avancée des pourparlers compte dans l'appréciation de la faute, mais elle ne suffit pas à elle seule. Le juge cherche aussi une rupture brutale, sans motif légitime, après avoir fait naître une confiance.", "f": "Les pourparlers et la bonne foi précontractuelle"}]}, {"id": "flashcards-qcm-penal-l2-s1", "matiere": "Droit pénal L2 S1", "total": 238, "fiches": 15, "questions": [{"q": "Selon l'article 130-1 du Code pénal, quelles sont les fonctions de la peine ?", "o": ["Sanctionner l'auteur de l'infraction", "Réparer le préjudice subi par la victime", "Favoriser l'amendement, l'insertion ou la réinsertion de l'auteur", "Neutraliser l'auteur dangereux par une mesure de sûreté"], "c": [0, 2], "j": "L'article 130-1 du Code pénal, issu de la loi du 15 août 2014, donne à la peine deux fonctions. Elle sanctionne l'auteur de l'infraction et favorise son amendement, son insertion ou sa réinsertion. B paraît proche du texte, car celui-ci impose de respecter les intérêts de la victime. La réparation de son préjudice passe toutefois par les dommages-intérêts, qu'elle demande en se constituant partie civile.", "f": "Les éléments introductifs du droit pénal"}, {"q": "Quel article de la Constitution donne aux traités régulièrement ratifiés une autorité supérieure à celle des lois ?", "o": ["L'article 34", "L'article 61-1", "L'article 55", "L'article 88-1"], "c": [2], "j": "L'article 55 de la Constitution donne aux traités régulièrement ratifiés ou approuvés une autorité supérieure à celle des lois, sous réserve de leur application par l'autre partie. Le juge pénal peut donc écarter une loi contraire à la Convention européenne des droits de l'homme. La proposition A est tentante en droit pénal, mais l'article 34 répartit les matières entre la loi et le règlement.", "f": "Les sources du droit pénal"}, {"q": "Quel article du Code pénal pose la classification tripartite des infractions ?", "o": ["L'article 111-2", "L'article 121-1", "L'article 111-1", "L'article 130-1"], "c": [2], "j": "L'article 111-1 du Code pénal classe les infractions, « suivant leur gravité, en crimes, délits et contraventions ». Le numéro de A est proche, car l'article 111-2 suit immédiatement. Il répartit pourtant la compétence entre la loi, pour les crimes et les délits, et le règlement, pour les contraventions. L'article 121-1, en B, pose que chacun répond pénalement de son propre fait.", "f": "La classification des infractions"}, {"q": "Quelle formule latine résume le principe de légalité criminelle ?", "o": ["Nemo tenetur se ipsum accusare", "In dubio pro reo", "Actus non facit reum nisi mens sit rea", "Nullum crimen, nulla poena sine lege"], "c": [3], "j": "Nullum crimen, nulla poena sine lege signifie « aucun crime, aucune peine sans loi ». Cette formule résume ainsi le principe de légalité. En revanche, la proposition A désigne le droit de ne pas contribuer à sa propre accusation, et B la règle selon laquelle le doute profite à la personne poursuivie. Enfin, la formule de C exige une intention coupable en plus de l'acte.", "f": "L'élément légal, le principe de légalité"}, {"q": "Selon l'article 112-1 du Code pénal, quels faits sont punissables ?", "o": ["Les faits punis par la loi au jour du jugement", "Les faits punis par la loi le jour où ils sont commis", "Les faits punis par la loi au jour de la plainte", "Les faits punis par la loi au jour des poursuites"], "c": [1], "j": "L'article 112-1 du Code pénal pose que « sont seuls punissables les faits constitutifs d'une infraction à la date à laquelle ils ont été commis ». Seule compte donc la loi en vigueur au moment de l'acte. La proposition A paraît logique, car le jugement intervient souvent des mois plus tard. Une loi plus sévère votée entre-temps reste sans effet sur ces faits.", "f": "Les corollaires du principe de légalité"}]}, {"id": "flashcards-qcm-biens-l2", "matiere": "Droit des biens L2", "total": 343, "fiches": 21, "questions": [{"q": "Une chose se trouve dans le commerce juridique. Quelles conséquences en découlent ?", "o": ["Elle peut faire l'objet d'une vente ou d'une donation", "Elle acquiert un patrimoine distinct de celui de son maître", "Elle peut, si c'est un immeuble, être grevée d'une hypothèque", "Elle devient insaisissable par les créanciers de son maître"], "c": [0, 2], "j": "Une chose dans le <strong>commerce juridique</strong> peut faire l'objet de conventions. Elle peut donc être vendue, donnée ou louée, et un immeuble peut en outre être grevé d'une hypothèque, sûreté qui garantit le paiement d'une dette. La proposition B est fausse, car seul un sujet de droit a un patrimoine. Pour la proposition D, c'est l'inverse, puisqu'un bien dans le commerce entre en principe dans le gage général des créanciers (art. 2284 C. civ.).", "f": "La distinction des personnes et des biens"}, {"q": "Que pose l'article 516 du Code civil ?", "o": ["Les biens se divisent en biens corporels et incorporels", "Les biens sont meubles, immeubles ou biens incorporels", "Les biens se divisent en choses fongibles et non fongibles", "Tous les biens sont meubles ou immeubles"], "c": [3], "j": "L'article 516 tient en une phrase, « Tous les biens sont meubles ou immeubles ». Tous les biens, y compris ceux qu'on ne peut pas toucher, entrent donc dans l'une de ces deux catégories. Ainsi, la loi range les parts sociales parmi les meubles (art. 529) et l'usufruit d'une maison parmi les immeubles (art. 526). La proposition B ajoute une troisième catégorie que le Code ignore. Les distinctions des propositions A et C existent bien, mais elles viennent de la doctrine et l'article 516 ne les pose pas.", "f": "La classification des biens"}, {"q": "Qu'est-ce qui distingue le droit réel du droit personnel ?", "o": ["Le droit réel lie deux personnes entre elles, le droit personnel porte directement sur une chose", "Le droit réel est toujours temporaire, le droit personnel peut être perpétuel", "Le droit réel porte sur une chose, le droit personnel lie un créancier à un débiteur", "Le droit réel naît de la loi, le droit personnel naît toujours d'un contrat"], "c": [2], "j": "Le <strong>droit réel</strong> donne à son titulaire un pouvoir direct sur une chose, sans passer par une autre personne, comme le propriétaire qui habite sa maison. Le <strong>droit personnel</strong>, ou droit de créance, permet à un créancier d'exiger une prestation d'un débiteur, par exemple le paiement d'un prix. La proposition A inverse les deux définitions. Pour la proposition D, un droit personnel peut naître d'un contrat, mais aussi d'un dommage causé à autrui (art. 1240 C. civ.).", "f": "Les droits réels et les droits personnels"}, {"q": "Pour la théorie classique d'Aubry et Rau, qu'est-ce que le patrimoine ?", "o": ["Un ensemble de biens immobiliers appartenant à une personne", "Une émanation de la personnalité, inséparable de la personne", "Une masse de biens affectée à un but, sans lien avec une personne", "Un contrat qui unit un débiteur à l'ensemble de ses créanciers"], "c": [1], "j": "Pour Aubry et Rau, auteurs du XIXe siècle, le <strong>patrimoine</strong> est une émanation de la personnalité. Il est lié à la personne comme son nom. Ainsi, toute personne a un patrimoine, même vide, et elle n'en a qu'un seul. À l'inverse, la proposition C résume la théorie concurrente du patrimoine d'affectation, venue de la doctrine allemande, qui rattache le patrimoine à un but. Le droit français s'en rapproche avec la fiducie et le statut de l'entrepreneur individuel.", "f": "Le patrimoine"}, {"q": "Qu'est-ce qui distingue la possession de la propriété ?", "o": ["La possession est un droit réel principal, la propriété une simple situation de fait", "La possession suppose toujours un titre de propriété écrit", "La propriété est protégée par la loi, la possession ne l'est jamais", "La possession est un fait, la propriété un droit, et elles peuvent être séparées"], "c": [3], "j": "La <strong>possession</strong> est la maîtrise de fait d'une chose (art. 2255 C. civ.), alors que la propriété est un droit. Ainsi, le voleur possède sans être propriétaire, et le propriétaire d'une voiture volée reste propriétaire sans la posséder. La proposition A inverse les deux notions. La proposition C est fausse, car la loi protège aussi la possession, notamment contre le trouble qui l'affecte ou la menace (art. 2278).", "f": "La notion de possession"}]}, {"id": "flashcards-qcm-da-l2-s2", "matiere": "Droit administratif L2 S2", "total": 377, "fiches": 25, "questions": [{"q": "Quelles conditions l'arrêt Narcy (CE Sect., 28 juin 1963) exige-t-il pour qu'une personne privée gère un service public ?", "o": ["Une mission d'intérêt général", "Un contrôle exercé par l'administration", "Des prérogatives de puissance publique", "Un financement majoritairement public"], "c": [0, 1, 2], "j": "Dans l'arrêt Narcy, le Conseil d'État qualifie de service public l'activité du Centre technique des industries de la fonderie, organisme privé. Il exige trois conditions cumulatives, à savoir une mission d'intérêt général, un contrôle de l'administration et des <strong>prérogatives de puissance publique</strong>, par exemple le pouvoir d'imposer des cotisations obligatoires. La proposition D est tentante, car le financement public compte parmi les éléments que le juge regarde depuis l'arrêt APREI, mais il n'a jamais été une condition de Narcy.", "f": "La notion de service public"}, {"q": "Quelle juridiction a rendu l'arrêt Bac d'Eloka, et à quelle date ?", "o": ["Le Conseil d'État, le 22 janvier 1921", "Le Tribunal des conflits, le 8 février 1873", "Le Tribunal des conflits, le 22 janvier 1921", "Le Conseil d'État, le 16 novembre 1956"], "c": [2], "j": "L'arrêt Société commerciale de l'Ouest africain, dit Bac d'Eloka, a été rendu par le <strong>Tribunal des conflits</strong> le 22 janvier 1921. Cette juridiction répartit les affaires entre le juge administratif et le juge judiciaire, ce qui explique son rôle ici. La proposition B est tentante, car le Tribunal des conflits a aussi rendu l'arrêt Blanco, mais cette décision date du 8 février 1873 et porte sur la responsabilité de l'État.", "f": "La distinction SPA / SPIC"}, {"q": "Quel auteur a rassemblé les principes du service public sous le nom de « lois du service public » ?", "o": ["Le doyen Maurice Hauriou", "Le doyen Léon Duguit", "Le professeur Louis Rolland", "Le professeur Gaston Jèze"], "c": [2], "j": "Dans les années 1930, le professeur Louis Rolland a regroupé dans son précis les règles communes à tous les services publics, d'où le nom de « lois de Rolland ». La proposition B est tentante, car Léon Duguit est le grand théoricien du service public. Toutefois, il en faisait le critère du droit administratif, alors que Rolland a présenté les règles que tout service public doit respecter.", "f": "Les lois du service public"}, {"q": "Dans la régie directe, le service public a-t-il une personnalité juridique propre ?", "o": ["Oui, celle d'un établissement public rattaché à la commune", "Oui, mais seulement pour conclure ses propres contrats", "Non, sauf si le conseil municipal lui vote un budget annexe", "Non, il se confond avec la personne publique qui le gère"], "c": [3], "j": "Dans la <strong>régie directe</strong>, la collectivité gère le service avec ses propres agents et son budget général. Aucune personne juridique nouvelle n'apparaît, si bien que les contrats et les décisions sont pris au nom de la collectivité. On choisirait facilement la proposition C, car le budget annexe existe dans la régie dotée de l'autonomie financière. Mais ce budget distinct permet seulement de suivre les comptes du service, sans lui donner de personnalité juridique.", "f": "Les modes de gestion du service public"}, {"q": "Qui est compétent pour créer un service public national important en matière d'enseignement ou de sécurité sociale ?", "o": ["Le Premier ministre, par un décret en Conseil d'État", "Le ministre concerné, par un arrêté ministériel", "Le Parlement, par une loi", "Le gouvernement, par une simple circulaire"], "c": [2], "j": "L'article 34 de la Constitution réserve à la loi les principes fondamentaux de l'enseignement et de la sécurité sociale. La création d'un grand service public national dans ces domaines touche ces principes, si bien que le Parlement doit intervenir. La proposition A peut tromper, car le gouvernement exerce le pouvoir réglementaire. Il peut toutefois seulement organiser le service dans le cadre fixé par la loi, par exemple en précisant son fonctionnement.", "f": "La création et la suppression du service public"}]}, {"id": "flashcards-qcm-obligations-l2-s2", "matiere": "Droit des obligations L2 S2", "total": 371, "fiches": 23, "questions": [{"q": "Un automobiliste blesse un piéton en roulant à 140 km/h en ville. Quelles conséquences relèvent de sa responsabilité civile ?", "o": ["Une peine d'amende ou d'emprisonnement pour blessures involontaires", "La prise en charge des frais médicaux et du préjudice moral du piéton", "Un retrait de points ou une suspension de son permis de conduire", "Une condamnation à verser des dommages et intérêts au piéton"], "c": [1, 3], "j": "La responsabilité civile se traduit par des <strong>dommages et intérêts</strong> versés à la victime, qui couvrent ici ses frais médicaux et son préjudice moral, d'ailleurs sur le fondement de la loi du 5 juillet 1985 puisqu'un véhicule est impliqué. La peine de la proposition A relève de la responsabilité pénale, qui punit l'auteur au nom de la société (articles 222-19 et 222-20 du Code pénal). La mesure de la proposition C est une sanction administrative prévue par le Code de la route. Ces responsabilités peuvent se cumuler pour le même accident.", "f": "La notion et les fonctions de la responsabilité civile"}, {"q": "Quelle est la finalité principale de la responsabilité pénale ?", "o": ["Rétablir l'équilibre patrimonial détruit par le dommage", "Indemniser la victime de l'infraction à hauteur de son préjudice", "Punir l'auteur au nom de la société et protéger l'ordre public", "Garantir la sécurité de la victime par un fonds d'indemnisation"], "c": [2], "j": "La responsabilité pénale sanctionne l'auteur d'une infraction par une peine, comme l'amende ou l'emprisonnement, au nom de la société. La proposition B décrit la responsabilité civile, qui répare le dommage de la victime, et la proposition A reprend la formule de la Cour de cassation sur la réparation intégrale. La victime peut d'ailleurs obtenir cette réparation devant le juge pénal, mais par une action civile distincte de la peine (articles 2 et 3 du Code de procédure pénale).", "f": "La distinction des responsabilités"}, {"q": "Qu'interdit le principe du <strong>non-cumul</strong> des responsabilités ?", "o": ["Au juge de prononcer deux condamnations pour le même dommage", "Au cocontractant d'agir en délictuel pour un dommage né du contrat", "Au tiers victime d'invoquer le manquement d'un contrat conclu par d'autres", "À la victime de cumuler une indemnité et une peine contre le même auteur"], "c": [1], "j": "Le non-cumul vise le créancier d'une obligation contractuelle. Quand son dommage résulte de l'inexécution du contrat, il doit agir sur le fondement contractuel et ne peut pas choisir l'article 1240 du Code civil pour écarter les règles du contrat. La proposition C est le piège, car le tiers peut justement invoquer ce manquement sur le fondement délictuel depuis l'arrêt Boot shop (Assemblée plénière, 6 octobre 2006). D'ailleurs, le mot « cumul » désigne ici un choix entre deux régimes, sans rapport avec un cumul d'indemnités.", "f": "La frontière entre contractuel et extracontractuel"}, {"q": "Quelle différence sépare le dommage du préjudice ?", "o": ["Le dommage est l'atteinte brute, le préjudice ses suites chiffrables", "Les deux mots sont synonymes et le juge les emploie indifféremment", "Le dommage vise le corps, le préjudice vise les biens", "Le préjudice est le fait brut, le dommage sa traduction chiffrée"], "c": [0], "j": "Le <strong>dommage</strong> est l'atteinte elle-même, par exemple la jambe cassée d'un piéton renversé par un vélo. Les <strong>préjudices</strong> sont les conséquences de cette atteinte que le juge chiffre en euros, comme les frais médicaux, la perte de salaire ou la douleur. Un seul dommage produit donc plusieurs préjudices, indemnisés séparément. La proposition D inverse les deux notions. La proposition B décrit l'usage ancien de la jurisprudence, avant que la nomenclature Dintilhac de 2005 consacre la distinction.", "f": "Le dommage, le préjudice et ses caractères"}, {"q": "Qu'est-ce que la consolidation en droit du dommage corporel ?", "o": ["La date à laquelle la victime reprend son activité professionnelle", "La date à laquelle le tribunal statue sur la responsabilité", "La date à laquelle la victime reçoit sa dernière indemnité", "La date à laquelle l'état de santé de la victime se stabilise"], "c": [3], "j": "La <strong>consolidation</strong> est le moment où les lésions se fixent et prennent un caractère permanent, si bien qu'un traitement n'est plus nécessaire, sauf pour éviter une aggravation. Elle sert de frontière entre préjudices temporaires et préjudices permanents, et elle fait courir le délai de dix ans de l'article 2226 du Code civil. La proposition A est tentante, mais une victime peut être consolidée sans pouvoir reprendre son travail, et elle est alors indemnisée de ses pertes de gains futurs.", "f": "Les chefs de préjudice (nomenclature Dintilhac)"}]}, {"id": "flashcards-qcm-contrats-speciaux-l3", "matiere": "Contrats spéciaux L3", "total": 343, "fiches": 20, "questions": [{"q": "Quelles règles l'article 1105 du Code civil pose-t-il ?", "o": ["Les contrats sans dénomination propre restent soumis aux règles générales du droit des contrats.", "La liste des contrats nommés par le Code civil est limitative, les parties ne peuvent pas en inventer.", "Les règles générales prévalent sur les règles propres à un contrat lorsque les deux se contredisent.", "Les règles particulières à un contrat nommé l'emportent sur les règles générales en cas de conflit."], "c": [0, 3], "j": "D'après l'article 1105, tous les contrats, nommés ou innommés, reçoivent les règles générales du droit des contrats, et ces règles s'appliquent « sous réserve » des règles particulières. La règle spéciale l'emporte donc sur la règle générale, selon l'adage specialia generalibus derogant. La proposition C inverse cette priorité, puisqu'elle fait passer la règle générale avant la règle spéciale. La proposition B oublie la liberté contractuelle de l'article 1102, qui permet d'inventer des contrats.", "f": "La notion de contrat spécial"}, {"q": "Après plusieurs mois de discussions, une société met fin sans prévenir à des pourparlers déjà avancés pour une cession d'actions. Que peut obtenir le partenaire victime de cette rupture fautive ?", "o": ["Le remboursement des frais de négociation et des études préalables", "La perte de chance de réaliser les gains que la cession lui aurait procurés", "Les gains que la cession lui aurait procurés si elle avait été conclue", "L'exécution forcée de la cession aux conditions du dernier projet discuté"], "c": [0], "j": "Dans l'arrêt Manoukian (chambre commerciale, 26 novembre 2003, n° 00-10.243), la Cour de cassation limite la réparation aux frais de négociation et d'études. L'article 1112, alinéa 2, du Code civil reprend cette solution depuis 2016. Beaucoup d'étudiants choisissent la proposition B, mais la faute dans la rupture ne cause pas la perte d'une chance de réaliser les gains espérés, puisque la victime n'avait aucun droit à la conclusion du contrat.", "f": "Les avant-contrats de la vente"}, {"q": "Dans l'affaire du Poussin (Civ. 1re, 22 février 1978), pourquoi la Cour de cassation casse-t-elle l'arrêt d'appel ?", "o": ["Les juges n'avaient pas recherché le dol des musées nationaux, acheteurs du tableau.", "Les juges n'avaient pas recherché si les vendeurs s'étaient trompés sur l'auteur du tableau.", "Les juges avaient admis la vente malgré un prix dérisoire, sans contrepartie réelle.", "Les juges avaient refusé d'annuler la préemption exercée par l'État lors des enchères."], "c": [1], "j": "Dans cet arrêt (n° 76-11.551), la première chambre civile reproche à la cour d'appel de ne pas avoir recherché si le consentement des vendeurs avait été vicié par leur conviction erronée que le tableau ne pouvait pas être de Poussin. Le fondement est l'erreur sur une qualité essentielle, ici l'auteur de l'œuvre. Beaucoup d'étudiants choisissent la proposition A, mais le dol suppose une tromperie de l'acheteur, que les vendeurs n'invoquaient pas devant la Cour.", "f": "Le consentement, la capacité et le pouvoir"}, {"q": "Qu'est-ce qu'une chose future en droit de la vente ?", "o": ["Une chose encore inexistante au jour de la vente, appelée à exister plus tard", "Une chose qui existe déjà, mais dont le prix sera fixé plus tard par un expert", "Une chose qui appartient encore à un tiers au jour où la vente est conclue", "Une chose qui a disparu avant la vente sans que les parties le sachent"], "c": [0], "j": "L'article 1163 du Code civil admet qu'un contrat porte sur une prestation présente ou future. Par exemple, un agriculteur peut vendre en mars la récolte de blé qu'il moissonnera en juillet. Beaucoup d'étudiants choisissent la proposition C, mais elle décrit la vente de la chose d'autrui, qui relève de l'article 1599. La proposition D correspond à la chose périe avant la vente, que l'article 1601 frappe de nullité.", "f": "La chose vendue"}, {"q": "Que prévoit l'article 1591 du Code civil sur le prix de la vente ?", "o": ["Le prix doit être fixé par un tiers choisi par les deux parties.", "Le prix est présumé égal à la valeur du bien sur le marché.", "Le prix doit être déterminé et désigné par les parties.", "Le prix peut être fixé plus tard, par un nouvel accord des parties."], "c": [2], "j": "L'article 1591 du Code civil exige un prix déterminé et désigné par les parties. Le contrat doit donc donner un montant ou une méthode de calcul qui ne dépend plus d'une nouvelle discussion, par exemple le cours d'une matière première à une date fixée. Beaucoup d'étudiants choisissent la proposition A, mais le recours à un tiers est une simple faculté que l'article 1592 ouvre aux parties.", "f": "Le prix"}]}, {"id": "flashcards-qcm-commercial-l3-s1", "matiere": "Droit commercial L3 S1", "total": 390, "fiches": 23, "questions": [{"q": "Quelles matières relèvent du droit des affaires sans appartenir au droit commercial au sens strict ?", "o": ["Le régime des actes de commerce", "Le droit des sociétés", "La propriété industrielle", "Le fonds de commerce"], "c": [1, 2], "j": "Le droit des affaires englobe le droit commercial et y ajoute d'autres matières de la vie des entreprises, notamment le droit des sociétés et la propriété industrielle, qui protège les brevets et les marques. Les actes de commerce et le fonds de commerce, en A et D, forment au contraire le noyau du droit commercial au sens strict, avec le statut du commerçant.", "f": "Qu'est-ce que le droit commercial ?"}, {"q": "Qu'est-ce que la lex mercatoria médiévale ?", "o": ["Un droit né des usages des marchands, commun à plusieurs pays et appliqué par leurs juges", "Un code royal rédigé sous Colbert en 1673 pour unifier les règles du commerce terrestre", "Un recueil de lois votées par les assemblées révolutionnaires pour libérer le commerce", "Le droit romain du commerce maritime, repris tel quel par les grandes cités marchandes italiennes"], "c": [0], "j": "La lex mercatoria est née de la pratique des marchands, en dehors de l'État, notamment aux foires de Champagne aux XIIe et XIIIe siècles. Ainsi, les mêmes usages s'appliquaient d'une ville à l'autre, et des juges choisis parmi les marchands tranchaient les litiges. La proposition B renvoie à l'ordonnance de Colbert de 1673, un texte royal bien postérieur. La proposition C vise la période révolutionnaire, qui a surtout proclamé la liberté du commerce.", "f": "L'histoire et les sources du droit commercial"}, {"q": "Un particulier achète un lot de 50 vélos d'occasion pour les remettre en état et les revendre sur internet. Il ne recommence jamais. Cet achat est-il un acte de commerce ?", "o": ["Non, car une opération unique ne peut pas être un acte de commerce", "Oui, car c'est un achat de meubles pour les revendre, même isolé", "Non, car l'acheteur n'est pas commerçant et n'a pas l'intention de le devenir", "Oui, mais seulement si la revente lui procure un bénéfice réel"], "c": [1], "j": "L'article L110-1, 1° du Code de commerce répute acte de commerce tout achat de biens meubles pour les revendre, en l'état ou après les avoir travaillés. Les vélos sont achetés, ce sont des meubles, et l'acheteur veut les revendre dès l'achat. Une seule opération suffit, c'est un acte de commerce isolé. La proposition D semble juste, mais l'intention de faire un bénéfice suffit, même si la revente se fait finalement à perte.", "f": "Les actes de commerce par nature"}, {"q": "Qu'est-ce qui rend la lettre de change commerciale, selon l'article L110-1, 10° du Code de commerce ?", "o": ["L'objet commercial de l'opération que la lettre sert à payer au fournisseur", "Le montant de la somme, dès qu'elle dépasse le seuil civil de 1 500 euros", "Sa forme seule, quels que soient son objet et la qualité du signataire", "La qualité de commerçant de celui qui la signe en qualité de tireur"], "c": [2], "j": "L'article L110-1, 10° répute actes de commerce, « entre toutes personnes, les lettres de change ». La forme du titre suffit donc, sans regarder qui le signe ni ce qu'il sert à payer. La proposition A décrit en revanche le billet à ordre, qui est commercial ou civil selon l'opération qui lui a donné naissance. La proposition D décrit la logique de l'accessoire, sans rapport avec la commercialité par la forme.", "f": "Les actes de commerce par la forme et par accessoire"}, {"q": "Qu'est-ce qu'un acte mixte en droit commercial ?", "o": ["Un acte commercial pour l'une des parties et civil pour l'autre", "Une troisième catégorie d'actes, soumise à un régime propre que fixe la loi", "Un acte conclu entre deux non-commerçants à propos d'une activité commerciale", "Un acte qui mêle des clauses civiles et commerciales pour les deux parties"], "c": [0], "j": "L'acte mixte est un seul contrat qui n'a pas la même nature pour les deux parties. Il est ainsi commercial pour celle qui agit dans son commerce et civil pour l'autre, comme la vente d'un ordinateur par un magasin à un particulier. La proposition B semble juste, mais aucun texte ne crée une catégorie à part, et les juges appliquent à chaque partie les règles de sa propre qualité.", "f": "Les actes mixtes et le régime distributif"}]}, {"id": "flashcards-qcm-societes-l3-s1", "matiere": "Droit des sociétés L3 S1", "total": 436, "fiches": 26, "questions": [{"q": "Qu'apporte la personnalité morale à une société immatriculée ?", "o": ["Un patrimoine propre, distinct de celui de chaque associé", "La limitation de la responsabilité des associés à leurs apports", "La capacité de contracter et d'agir en justice en son nom", "La qualité de commerçant pour chacun de ses associés"], "c": [0, 2], "j": "Dès son immatriculation, la société devient une personne morale (article 1842 du Code civil). Elle a donc son propre patrimoine, et elle signe des contrats ou agit en justice en son nom, comme une personne physique. On peut hésiter avec la proposition B, mais une société en nom collectif a elle aussi la personnalité morale, alors que ses associés répondent des dettes sur leurs biens personnels. La qualité de commerçant, en D, appartient aux seuls associés de SNC (article L. 221-1 du Code de commerce).", "f": "La société, notion, fonctions, enjeux"}, {"q": "Quel critère distingue la société de l'association ?", "o": ["La réalisation de bénéfices par le groupement", "La personnalité morale du groupement", "La distribution des bénéfices aux membres", "L'exercice d'une activité économique régulière"], "c": [2], "j": "D'après l'article 1er de la loi du 1er juillet 1901, l'association poursuit un but autre que le partage de bénéfices entre ses membres. La société est au contraire constituée pour partager le bénéfice ou l'économie qui en résulte (article 1832 du Code civil). La proposition A peut tromper, car beaucoup pensent qu'une association doit fonctionner à perte. En réalité, elle peut réaliser des excédents, à condition de les garder pour ses activités.", "f": "La société face aux groupements voisins"}, {"q": "Dans quels articles se trouvent les règles communes à toutes les sociétés, civiles comme commerciales ?", "o": ["Les articles 1845 à 1870-1 du Code civil", "Les articles L. 210-1 à L. 210-9 du Code de commerce", "Les articles 1832 à 1844-17 du Code civil", "Les articles 1871 à 1873 du Code civil"], "c": [2], "j": "Les articles 1832 à 1844-17 du Code civil forment le droit commun des sociétés. D'après l'article 1834, ils s'appliquent à toutes les sociétés, sauf si la loi prévoit une autre règle en raison de leur forme ou de leur objet. La proposition B est tentante, car les articles L. 210-1 et suivants ouvrent le livre II du Code de commerce. Ils concernent pourtant les seules sociétés commerciales. Les articles 1845 et suivants, en A, règlent la société civile.", "f": "Les sources et l'évolution du droit des sociétés"}, {"q": "Quel texte rend la SARL commerciale, quel que soit son objet ?", "o": ["L'article 1845, alinéa 2, du Code civil", "L'article L. 223-1 du Code de commerce", "L'article L. 110-1 du Code de commerce", "L'article L. 210-1 du Code de commerce"], "c": [3], "j": "L'article L. 210-1 du Code de commerce rend commerciales par leur forme, quel que soit leur objet, la SNC, la commandite simple, la SARL et les sociétés par actions. On peut hésiter avec la proposition C, car l'article L. 110-1 donne la liste des actes de commerce. Il sert pourtant à la commercialité par l'objet, qui joue pour les sociétés dont la forme ne suffit pas à fixer le caractère, comme la société civile. L'article 1845, en A, fait de la société civile la catégorie par défaut.", "f": "La classification des sociétés"}, {"q": "Comment l'article 1832, alinéa 1er, du Code civil qualifie-t-il la société ?", "o": ["Comme une institution dotée d'un intérêt propre", "Comme un contrat entre deux ou plusieurs personnes", "Comme une personne morale dès la signature des statuts", "Comme un patrimoine affecté à une activité"], "c": [1], "j": "L'article 1832 du Code civil prévoit que deux ou plusieurs personnes « conviennent par un contrat » d'affecter des biens ou leur travail à une entreprise commune. La thèse contractuelle s'appuie sur ces mots. La proposition C peut tromper, car la société devient bien une personne morale. Pourtant, elle le devient seulement à son immatriculation (article 1842), et l'article 1832 ne parle pas de personnalité.", "f": "La nature juridique de la société"}]}, {"id": "flashcards-qcm-travail-l3-s1", "matiere": "Droit du travail L3 S1", "total": 426, "fiches": 21, "questions": [{"q": "D'après l'arrêt Société générale (Cass. soc., 13 novembre 1996), quels pouvoirs de l'employeur caractérisent le lien de subordination ?", "o": ["Donner des ordres et des directives", "Contrôler l'exécution du travail", "Fournir le matériel et fixer le lieu de travail", "Sanctionner les manquements du subordonné"], "c": [0, 1, 3], "j": "L'arrêt Société générale définit le lien de subordination comme l'exécution d'un travail sous l'autorité d'un employeur qui a le pouvoir de donner des ordres et des directives, d'en contrôler l'exécution et de sanctionner les manquements de son subordonné. Les propositions A, B et D reprennent donc ces trois pouvoirs. La proposition C est tentante, mais fournir le matériel ou fixer le lieu de travail sont seulement des indices que le juge examine pour savoir si ces trois pouvoirs existent.", "f": "La notion, le domaine et les acteurs du droit du travail"}, {"q": "Quand l'Organisation internationale du travail (OIT) a-t-elle été créée ?", "o": ["En 1945, avec la Charte des Nations unies", "En 1919, dans le cadre du traité de Versailles", "En 1946, avec le Préambule de la Constitution", "En 1958, avec la Constitution de la Ve République"], "c": [1], "j": "L'OIT naît en 1919 avec le traité de Versailles, qui met fin à la Première Guerre mondiale. Sa constitution figure dans la partie XIII de ce traité, et l'organisation adopte depuis des conventions que les États choisissent de ratifier. La proposition A est tentante, car l'ONU date de 1945, mais l'OIT existait déjà et elle est seulement devenue en 1946 la première institution spécialisée des Nations unies.", "f": "Les sources du droit du travail"}, {"q": "Quels critères cumulatifs la jurisprudence exige-t-elle pour caractériser un contrat de travail ?", "o": ["Une prestation de travail, une rémunération et un lien de subordination", "Une prestation de travail, une rémunération et un contrat écrit signé", "Une prestation personnelle, une rémunération et une durée minimale de travail", "Une prestation de travail, un lien de subordination et une immatriculation"], "c": [0], "j": "Le contrat de travail suppose qu'une personne fournisse une prestation de travail, contre une rémunération, sous la subordination d'un employeur. Les trois critères sont cumulatifs, donc un bénévole qui reçoit des consignes sans être payé reste en dehors du salariat. La proposition B est tentante, mais l'écrit n'est pas un critère, car un CDI à temps plein peut être conclu oralement. L'immatriculation, en D, crée seulement une présomption simple de travail indépendant (article L. 8221-6 du Code du travail).", "f": "La qualification du contrat de travail"}, {"q": "Sur quel fondement constitutionnel repose la liberté d'embauche de l'employeur ?", "o": ["La liberté d'entreprendre, tirée de l'article 4 de la Déclaration de 1789", "Le droit d'obtenir un emploi, posé par le Préambule de 1946", "Le droit de propriété, garanti par l'article 17 de la Déclaration", "La liberté syndicale, posée par l'alinéa 6 du Préambule de 1946"], "c": [0], "j": "Le Conseil constitutionnel rattache la liberté d'entreprendre à l'article 4 de la Déclaration de 1789, et la liberté de choisir ses collaborateurs en découle. L'employeur choisit donc librement ses salariés, dans le respect des interdictions de discrimination. La proposition B est tentante, car le droit d'obtenir un emploi figure dans le Préambule de 1946, mais il protège le travailleur et sert plutôt à encadrer cette liberté.", "f": "Le recrutement et l'embauche"}, {"q": "Quel texte pose le principe selon lequel le CDI est la forme normale et générale de la relation de travail ?", "o": ["L'article L. 1242-1 du Code du travail", "L'article L. 1221-2 du Code du travail", "L'article 1103 du Code civil", "L'article L. 1231-1, alinéa 1er, du Code du travail"], "c": [1], "j": "L'article L. 1221-2 du Code du travail dispose que le contrat à durée indéterminée est la forme normale et générale de la relation de travail, puis il renvoie aux cas limités où un terme peut être fixé. La proposition A est tentante, car l'article L. 1242-1 protège aussi le CDI, mais il interdit au CDD de pourvoir durablement un emploi permanent sans poser le principe lui-même. L'article L. 1231-1, en D, organise la rupture du CDI.", "f": "Le CDI et la période d'essai"}]}];
